import type { Locale } from '@/types/app'

/** A nested object whose leaves are translated strings. */
export type MessageTree = {
  [key: string]: string | MessageTree
}

/** Joins a prefix and key using a dot separator. */
type Join<Prefix extends string, Key extends string> = Prefix extends '' ? Key : `${Prefix}.${Key}`

/** Builds the union of dot-notation paths for a nested tree of strings. */
export type FlattenKeys<T extends Record<string, unknown>, Prefix extends string = ''> = {
  [K in keyof T & string]: T[K] extends string
    ? Join<Prefix, K>
    : T[K] extends Record<string, unknown>
      ? FlattenKeys<T[K], Join<Prefix, K>>
      : never
}[keyof T & string]

