export type MessageCatalog = typeof fr

/** Deep readonly translation tree shared by every locale. */
export type Translation = {
  readonly [K in keyof MessageCatalog]: MessageCatalog[K] extends string
    ? string
    : MessageCatalog[K] extends MessageTree
      ? DeepReadonly<MessageCatalog[K]>
      : never
}

export type DeepReadonly<T extends MessageTree> = {
  readonly [K in keyof T]: T[K] extends string
    ? string
    : T[K] extends MessageTree
      ? DeepReadonly<T[K]>
      : never
}

/** Every valid translation key, e.g. "nav.students". */
export type TranslationKey = FlattenKeys<MessageCatalog> | `finance.${string}` | `documents.${string}`

/** Map of every supported locale to its translation tree. */
export type Translations = Record<Locale, Translation>
